const char* dev_path = "/dev/ttyS0";

// O_NOCTTY prevents device from becoming the controlling terminal.
// Essential for serial communication setup/daemon processes.
int flags = O_RDWR | O_NOCTTY | O_NONBLOCK;

int fd = open(dev_path, flags);

if (fd == -1) {
    // Error handling (e.g., device missing/permissions)
    return;
}

// fd is open for I/O but won't interfere with session control.

close(fd);
